<?php
require_once __DIR__.'/inc/auth.php';$u=require_login();$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$old=$_POST['old']??'';$new=$_POST['new']??'';$confirm=$_POST['confirm']??'';$s=db()->prepare('SELECT password_hash FROM users WHERE id=?');$s->execute([$u['id']]);$h=$s->fetchColumn();if(!password_verify($old,$h))$err='Current password is incorrect.';elseif(strlen($new)<8)$err='New password must be at least 8 characters.';elseif($new!==$confirm)$err='New passwords do not match.';else{$s=db()->prepare('UPDATE users SET password_hash=? WHERE id=?');$s->execute([password_hash($new,PASSWORD_DEFAULT),$u['id']]);$msg='Password changed successfully.';}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Change Password</title><link rel="stylesheet" href="assets/app.css"></head><body><div class="auth-shell"><div class="card"><div class="row between"><div><div class="brand">Change Password</div><div class="sub"><?=e($u['full_name'])?></div></div><a href="dashboard.php">Back</a></div><?php if($msg):?><div class="notice"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="notice error"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Current password</label><input type="password" name="old" required></div><div class="field"><label>New password</label><input type="password" name="new" required></div><div class="field"><label>Confirm new password</label><input type="password" name="confirm" required></div><button class="btn primary">Update password</button></form></div></div></body></html>
